package main

import (
	"bytes"
	"encoding/base64"
	"encoding/json"
	"fmt"
	neturl "net/url"
	"os"
	"os/exec"
	"strings"
	"text/template"
	"unicode"
)

// brewFormulaTemplate is the formula Goreleaser generated, so that formulas keep the same
// shape whichever builder released them.
var brewFormulaTemplate = template.Must(template.New("formula").Parse(`# typed: false
# frozen_string_literal: true

# This file was generated by sfreleaser. DO NOT EDIT.
class {{ .Class }} < Formula
  desc ""
  homepage "{{ .Homepage }}"
  version "{{ .Version }}"
{{- with .License }}
  license "{{ . }}"
{{- end }}
{{- with .Darwin }}

  on_macos do
{{- with .Intel }}
    if Hardware::CPU.intel?
      url "{{ .URL }}"
      sha256 "{{ .SHA256 }}"

      define_method(:install) do
        bin.install "{{ $.Binary }}"
      end
    end
{{- end }}
{{- with .Arm }}
    if Hardware::CPU.arm?
      url "{{ .URL }}"
      sha256 "{{ .SHA256 }}"

      define_method(:install) do
        bin.install "{{ $.Binary }}"
      end
    end
{{- end }}
  end
{{- end }}
{{- with .Linux }}

  on_linux do
{{- with .Intel }}
    if Hardware::CPU.intel? && Hardware::CPU.is_64_bit?
      url "{{ .URL }}"
      sha256 "{{ .SHA256 }}"
      define_method(:install) do
        bin.install "{{ $.Binary }}"
      end
    end
{{- end }}
{{- with .Arm }}
    if Hardware::CPU.arm? && Hardware::CPU.is_64_bit?
      url "{{ .URL }}"
      sha256 "{{ .SHA256 }}"
      define_method(:install) do
        bin.install "{{ $.Binary }}"
      end
    end
{{- end }}
  end
{{- end }}
end
`))

type brewFormulaAsset struct {
	URL    string
	SHA256 string
}

type brewFormulaPlatform struct {
	Intel *brewFormulaAsset
	Arm   *brewFormulaAsset
}

type brewFormulaModel struct {
	Class    string
	Homepage string
	Version  string
	License  string
	Binary   string
	Darwin   *brewFormulaPlatform
	Linux    *brewFormulaPlatform
}

// renderBrewFormula renders the formula installing the binary from the release archives.
func renderBrewFormula(global *GlobalModel, version string, archives []nativeArchive) (string, error) {
	repository := "https://github.com/" + global.Owner + "/" + global.Project
	model := brewFormulaModel{
		Class:    brewFormulaClass(global.Project),
		Homepage: repository,
		Version:  strings.TrimPrefix(version, "v"),
		License:  global.License,
		Binary:   global.Binary,
	}

	for _, archive := range archives {
		platform := &model.Linux
		if archive.Target.GOOS == "darwin" {
			platform = &model.Darwin
		}
		if *platform == nil {
			*platform = &brewFormulaPlatform{}
		}

		asset := &brewFormulaAsset{
			URL:    repository + "/releases/download/" + version + "/" + archive.Name,
			SHA256: archive.SHA256,
		}

		switch archive.Target.GOARCH {
		case "amd64":
			(*platform).Intel = asset
		case "arm64":
			(*platform).Arm = asset
		}
	}

	var formula bytes.Buffer
	if err := brewFormulaTemplate.Execute(&formula, model); err != nil {
		return "", err
	}

	return formula.String(), nil
}

// brewFormulaClass is the Ruby class Homebrew expects for a formula name, 'firehose-core'
// being 'FirehoseCore'.
func brewFormulaClass(name string) string {
	var class strings.Builder
	upper := true
	for _, r := range name {
		if !unicode.IsLetter(r) && !unicode.IsDigit(r) {
			upper = true
			continue
		}

		if upper {
			r = unicode.ToUpper(r)
			upper = false
		}
		class.WriteRune(r)
	}

	return class.String()
}

// brewFormulaUpdate is what [publishBrewFormula] changed in the tap.
type brewFormulaUpdate struct {
	// Unchanged is true when the tap's default branch already had the formula.
	Unchanged bool
	// PullRequest is the URL of the pull request, empty when committed straight to the
	// default branch.
	PullRequest string
	// Commit is the commit holding the formula.
	Commit string
}

// publishBrewFormula commits the formula of the release to the tap, directly on its default
// branch or through a pull request, with HOMEBREW_TAP_TOKEN when set.
func publishBrewFormula(global *GlobalModel, release *ReleaseModel, archives []nativeArchive) (*brewFormulaUpdate, error) {
	formula, err := renderBrewFormula(global, release.Version, archives)
	if err != nil {
		return nil, fmt.Errorf("rendering Homebrew formula: %w", err)
	}

	tap := release.Brew.TapRepoOwner + "/" + release.Brew.TapRepoName
	path := global.Project + ".rb"
	message := fmt.Sprintf("Brew formula update for %s version %s", global.Project, release.Version)

	var repository struct {
		DefaultBranch string `json:"default_branch"`
	}
	if err := ghAPIJSON(&repository, "repos/"+tap); err != nil {
		return nil, fmt.Errorf("reading tap %s: %w", tap, err)
	}

	if current, found := tapFileContent(tap, path, repository.DefaultBranch); found && current == formula {
		fmt.Printf("Homebrew formula %s in %s is already up to date\n", path, tap)
		return &brewFormulaUpdate{Unchanged: true}, nil
	}

	branch := repository.DefaultBranch
	if release.Brew.PullRequest {
		// Goreleaser's branch name, reused as is when it exists, as Goreleaser did.
		branch = global.Project + "-" + strings.TrimPrefix(release.Version, "v")
		if err := ensureBranch(tap, branch, repository.DefaultBranch); err != nil {
			return nil, err
		}
	}

	arguments := []string{"--method", "PUT", "repos/" + tap + "/contents/" + path,
		"-f", "message=" + message,
		"-f", "content=" + base64.StdEncoding.EncodeToString([]byte(formula)),
		"-f", "branch=" + branch,
	}
	if sha := tapFileSHA(tap, path, branch); sha != "" {
		arguments = append(arguments, "-f", "sha="+sha)
	}

	fmt.Printf("Updating Homebrew formula %s in %s (branch %s)\n", path, tap, branch)
	var written struct {
		Commit struct {
			SHA string `json:"sha"`
		} `json:"commit"`
	}
	if err := ghAPIJSON(&written, arguments...); err != nil {
		return nil, fmt.Errorf("updating %s in %s: %w", path, tap, err)
	}

	update := &brewFormulaUpdate{Commit: written.Commit.SHA}
	if !release.Brew.PullRequest {
		return update, nil
	}

	if _, err := runGH("pr", "create", "--repo", tap, "--base", repository.DefaultBranch, "--head", branch, "--title", message, "--body", "\n###### Automated with [sfreleaser](https://github.com/streamingfast/sfreleaser)"); err != nil {
		// A release run again updates the branch of the pull request it already opened.
		if !strings.Contains(err.Error(), "already exists") {
			return nil, fmt.Errorf("opening Homebrew formula pull request: %w", err)
		}
	}

	// 'pr create' prints no URL for an existing pull request. A fork's pull request with the
	// same branch name is ignored.
	url, err := runGH("pr", "list", "--repo", tap, "--head", branch, "--state", "open", "--json", "url,isCrossRepository", "--jq", "[.[] | select(.isCrossRepository == false)][0].url // empty")
	if err != nil {
		return nil, fmt.Errorf("finding Homebrew formula pull request: %w", err)
	}

	update.PullRequest = strings.TrimSpace(url)
	fmt.Printf("Homebrew formula pull request: %s\n", update.PullRequest)
	return update, nil
}

// tapFileContent is the content of path on branch, not found when the file does not exist yet.
func tapFileContent(tap, path, branch string) (string, bool) {
	var file struct {
		Content string `json:"content"`
	}
	if err := ghAPIJSON(&file, "repos/"+tap+"/contents/"+path+"?ref="+neturl.QueryEscape(branch)); err != nil {
		return "", false
	}

	content, err := base64.StdEncoding.DecodeString(strings.ReplaceAll(file.Content, "\n", ""))
	if err != nil {
		return "", false
	}

	return string(content), true
}

// ensureBranch creates branch on tap from the head of base, unless it already exists.
func ensureBranch(tap, branch, base string) error {
	if _, err := ghAPI("repos/" + tap + "/git/ref/heads/" + branch); err == nil {
		return nil
	}

	var head struct {
		Object struct {
			SHA string `json:"sha"`
		} `json:"object"`
	}
	if err := ghAPIJSON(&head, "repos/"+tap+"/git/ref/heads/"+base); err != nil {
		return fmt.Errorf("reading %s of %s: %w", base, tap, err)
	}

	_, err := ghAPI("--method", "POST", "repos/"+tap+"/git/refs", "-f", "ref=refs/heads/"+branch, "-f", "sha="+head.Object.SHA)
	return err
}

// tapFileSHA is the blob SHA of path on branch, empty when the file does not exist yet.
func tapFileSHA(tap, path, branch string) string {
	var file struct {
		SHA string `json:"sha"`
	}
	if err := ghAPIJSON(&file, "repos/"+tap+"/contents/"+path+"?ref="+neturl.QueryEscape(branch)); err != nil {
		return ""
	}

	return file.SHA
}

func ghAPIJSON(out any, arguments ...string) error {
	output, err := ghAPI(arguments...)
	if err != nil {
		return err
	}

	return json.Unmarshal([]byte(output), out)
}

func ghAPI(arguments ...string) (string, error) {
	return runGH(append([]string{"api"}, arguments...)...)
}

// runGH runs 'gh' with the tap token when HOMEBREW_TAP_TOKEN is set, the default 'gh'
// authentication otherwise.
func runGH(arguments ...string) (string, error) {
	cmd := exec.Command("gh", arguments...)
	cmd.Env = os.Environ()
	if token := homebrewTapToken(); token != "" {
		cmd.Env = append(cmd.Env, "GH_TOKEN="+token)
	}

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	if err := cmd.Run(); err != nil {
		return stdout.String(), fmt.Errorf("gh %s: %w: %s", arguments[0], err, strings.TrimSpace(stderr.String()))
	}

	return stdout.String(), nil
}

// ensureBrewTapReachable checks, before anything is built, that the token updating the formula
// can read the tap, HOMEBREW_TAP_TOKEN when set, the release token otherwise.
func ensureBrewTapReachable(brew *BrewReleaseModel) error {
	tap := brew.TapRepoOwner + "/" + brew.TapRepoName

	token, from := homebrewTapToken(), homebrewTapTokenEnv
	if token == "" {
		// The tap is usually public, any token can read it, so the release token would pass this
		// check while another run is the one writing the formula.
		if brew.Deferred {
			return fmt.Errorf("%s is required with --brew-deferred, 'publish-brew' updates the tap with it", homebrewTapTokenEnv)
		}

		token, from = mustGitHubToken(), "the release token"
	}

	cmd := exec.Command("gh", "api", "repos/"+tap, "--jq", ".permissions.push")
	cmd.Env = append(os.Environ(), "GH_TOKEN="+token)

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		return fmt.Errorf("%s cannot read the Homebrew tap %s: %w: %s", from, tap, err, strings.TrimSpace(stderr.String()))
	}

	// null for app tokens, and for user tokens the user's role rather than the token's scopes.
	if strings.TrimSpace(stdout.String()) == "false" {
		return fmt.Errorf("%s cannot push to the Homebrew tap %s", from, tap)
	}

	return nil
}
